import {$,$$,esc,showToast} from "./dom.js";
import {appState,supportedLanguages} from "./state.js";
import {renderAnnotations} from "./annotations.js";

const languageName=code=>supportedLanguages.find(item=>item[0]===code)?.[1]||code;
const selected=()=>appState.selectedLocales;
const values=()=>appState.message.values;
const rowIssue=code=>{const value=values()[code]||{};if(!value.title?.trim()||!value.body?.trim())return "title 和 body 均必填";if(value.title.length>100)return "title 超过 100 字符";if(value.body.length>200)return "body 超过 200 字符";return ""};
const allIssues=()=>selected().map(code=>[code,rowIssue(code)]).filter(([,issue])=>issue);

function matrix(){return `<div class="matrix-wrap"><table class="lang-matrix"><thead><tr><th style="width:150px">语言</th><th>Title</th><th>Body</th><th style="width:72px">操作</th></tr></thead><tbody>${selected().map(code=>{const value=values()[code]||{title:"",body:""},issue=rowIssue(code);return `<tr class="${issue?"is-error":""}"><td><strong>${esc(languageName(code))}</strong><div class="secondary-cell">${esc(code)}${code==="en-US"?" · 默认 fallback":""}</div>${issue?`<div class="form-error">${esc(issue)}</div>`:""}</td><td><textarea data-lang="${esc(code)}" data-key="title" maxlength="100" placeholder="Title">${esc(value.title)}</textarea></td><td><textarea data-lang="${esc(code)}" data-key="body" maxlength="200" placeholder="Body">${esc(value.body)}</textarea></td><td>${code==="en-US"?'<span class="secondary-cell">必填</span>':`<button class="op-link danger" data-remove-locale="${esc(code)}">移除</button>`}</td></tr>`}).join("")}</tbody></table></div>`}

function body(){const issues=allIssues();return `<div class="help-alert" data-anchor="language-import"><strong>KV 快速导入。</strong> 从 Excel / CSV 复制三列后粘贴：<code>locale[TAB]title[TAB]body</code>。首行可保留表头；同一 locale 会覆盖当前草稿。</div><div class="form-section"><div class="section-title"><h3>批量粘贴</h3><p>仅处理已在平台语言目录中的 locale</p></div><textarea class="el-textarea kv-paste" data-kv-paste placeholder="locale&#9;title&#9;body&#10;zh-CN&#9;检测到溢奶风险&#9;您的 S12 Pro 需要关注。"></textarea><div class="inline-actions"><button class="el-btn el-btn--primary" data-kv-import>导入到 KV 矩阵</button><span class="secondary-cell">导入 ${selected().length} 个语言；English 始终保留。</span></div></div><div class="form-section" data-anchor="lang-matrix"><div class="section-title"><h3>已导入语言 KV</h3><p>${selected().length} 行参与发布校验</p></div>${matrix()}</div><div class="form-section" data-anchor="language-validation"><div class="section-title"><h3>保存校验</h3><p>${issues.length?"存在阻断项":"已通过"}</p></div>${issues.length?`<div class="help-alert danger">${issues.map(([code,issue])=>`${languageName(code)}：${issue}`).join("；")}</div>`:'<div class="help-alert success">所有导入语言的 title/body 均可发布。</div>'}<p class="form-help">后续版本：文件导入/导出、翻译辅助和预填全部语言。</p></div>`}

function parsePaste(raw){const lines=raw.split(/\r?\n/).map(line=>line.trim()).filter(Boolean);const updates=[];const errors=[];lines.forEach((line,index)=>{const cols=line.split("\t");if(index===0&&cols[0].toLowerCase()==="locale")return;if(cols.length<3){errors.push(`第 ${index+1} 行缺少三列`);return}const [code,title,body]=cols;if(!supportedLanguages.some(item=>item[0]===code)){errors.push(`第 ${index+1} 行 locale 不在目录：${code}`);return}if(!title.trim()||!body.trim()||title.length>100||body.length>200){errors.push(`第 ${index+1} 行内容为空或超长`);return}updates.push({code,title,body})});return {updates,errors}}

export function openLanguageDrawer({onClose}={}){const root=$("#overlayRoot");root.insertAdjacentHTML("beforeend",`<div class="drawer-host is-open" id="languageDrawer" style="z-index:1400"><div class="drawer-mask" data-language-close></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="编辑多语言 KV"><header class="drawer-header"><div class="drawer-title"><h2>多语言 KV 快速导入</h2><p>${esc(appState.rule.name||"新推送规则")} · English 默认 fallback</p></div><button class="icon-btn" data-language-close>×</button></header><div class="drawer-main"><div class="drawer-body"><section class="drawer-content">${body()}</section></div></div><footer class="drawer-footer"><span class="save-hint">粘贴导入后可逐行修订</span><div class="footer-actions"><button class="el-btn" data-language-close>取消</button><button class="el-btn el-btn--primary" data-language-save>保存 KV</button></div></footer></aside></div>`);renderAnnotations("language","多语言 KV 快速导入");wire(onClose)}
function rerender(host,onClose){host.querySelector(".drawer-content").innerHTML=body();wireBody(host,onClose)}
function wireBody(host,onClose){host.querySelectorAll("[data-lang]").forEach(el=>el.addEventListener("input",()=>{values()[el.dataset.lang]??={title:"",body:""};values()[el.dataset.lang][el.dataset.key]=el.value}));host.querySelectorAll("[data-remove-locale]").forEach(el=>el.addEventListener("click",()=>{appState.selectedLocales=selected().filter(code=>code!==el.dataset.removeLocale);rerender(host,onClose)}));host.querySelector("[data-kv-import]")?.addEventListener("click",()=>{const raw=host.querySelector("[data-kv-paste]").value;const parsed=parsePaste(raw);if(parsed.errors.length){showToast(parsed.errors[0],"error");return}if(!parsed.updates.length){showToast("未识别到可导入语言行","error");return}parsed.updates.forEach(({code,title,body})=>{values()[code]={title,body};if(!selected().includes(code))appState.selectedLocales.push(code)});showToast(`已导入 ${parsed.updates.length} 行 KV`);rerender(host,onClose)})}
function wire(onClose){const host=$("#languageDrawer");host.querySelectorAll("[data-language-close]").forEach(el=>el.addEventListener("click",()=>close(onClose)));host.querySelector("[data-language-save]").addEventListener("click",()=>{if(allIssues().length){showToast("请补全当前 KV 矩阵中的必填内容","error");return}showToast("多语言 KV 已保存");close(onClose)});wireBody(host,onClose)}
function close(onClose){const host=$("#languageDrawer");if(!host)return;host.classList.remove("is-open");setTimeout(()=>{host.remove();onClose?.()},180)}
